create database mockaroo;
use mockaroo;

create table people (
	id INT PRIMARY KEY PRIMARY KEY,
	first_name VARCHAR(50),
	last_name VARCHAR(50),
	email VARCHAR(50),
	gender VARCHAR(50),
	ip_address VARCHAR(20)
);


create table messages (
	id INT PRIMARY KEY,
	content TEXT,
	person_id INT,
    FOREIGN KEY (person_id) REFERENCES people(id)
);


